contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, address recipient, uint256 amount) public {
        require(target != address(0), "target nonzero");
        require(recipient != address(0), "recipient nonzero");

        // owner (this contract) freezes target
        c.freezeAccount(target, true); if (__ESBMC_reverted()) return;

        // setup: give target some balance so a transfer would otherwise be possible
        // owner mints tokens to target (owner is this contract)
        c.mintToken(target, amount); if (__ESBMC_reverted()) return;

        uint256 senderBefore = c.balanceOf(target); if (__ESBMC_reverted()) return;
        uint256 recipientBefore = c.balanceOf(recipient); if (__ESBMC_reverted()) return;
        uint256 totalBefore = c.totalSupply(); if (__ESBMC_reverted()) return;

        // attempt transfer from frozen target: this contract is not target, so we cannot
        // call c.transfer from target. We need to call from target's context, but we cannot impersonate.
        // Instead, we can only test the effect of freezing on transfer if the caller is the frozen account.
        // Since msg.sender is this contract, we must freeze this contract itself to test transfer.
        // Re-express: freeze this contract, then attempt transfer from this contract.

        // Reset: freeze this contract instead
        c.freezeAccount(address(this), true); if (__ESBMC_reverted()) return;

        // this contract has balance? It has totalSupply initially (from constructor).
        uint256 myBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 recBefore = c.balanceOf(recipient); if (__ESBMC_reverted()) return;
        uint256 totalBefore2 = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.transfer(recipient, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 myAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 recAfter = c.balanceOf(recipient); if (__ESBMC_reverted()) return;
        uint256 totalAfter = c.totalSupply(); if (__ESBMC_reverted()) return;

        // General rule: if the sender is frozen, transfer must not move any tokens.
        // Either it reverts, or if it succeeds, balances and totalSupply remain unchanged.
        assert(reverted || (myBefore == myAfter && recBefore == recAfter && totalBefore2 == totalAfter));
    }

    receive() external payable {}
}

